        static void Require(bool value,string message){if(!value)throw new InvalidOperationException(message);}
        static IEnumerable<T> Children<T>(DependencyObject root) where T:DependencyObject
        {
            var own=root as T;if(own!=null)yield return own;foreach(object item in LogicalTreeHelper.GetChildren(root)){var child=item as DependencyObject;if(child!=null)foreach(var found in Children<T>(child))yield return found;}
        }
        static void Click(Button button){((IInvokeProvider)UIElementAutomationPeer.CreatePeerForElement(button).GetPattern(PatternInterface.Invoke)).Invoke();}
        static bool Inside(Rect outer,Rect inner){return inner.Left>=outer.Left-.1&&inner.Top>=outer.Top-.1&&inner.Right<=outer.Right+.1&&inner.Bottom<=outer.Bottom+.1;}
        static async Task ThemeChecks(ShellController shell,System.Windows.Forms.Screen screen)
        {
            foreach(int ui in (ReleaseFeatures.GlassUI?new[]{85,90,95}:new[]{85,90}))using(Glass95.WithDarkForFixture(false)){
                Preferences.Current.UIVersion=ui;shell.RefreshPanelTheme();shell.Quick=new QuickWindow(shell);shell.Quick.ShowAt(screen.Bounds,20,20,380,650);shell.Welcome=new WelcomeWindow(shell);shell.Welcome.ShowAt(screen.Bounds,420,20,760,720);shell.Welcome.SearchSettings.Text="투명도";shell.Welcome.OpenSettings("화면");var previous=shell.Welcome;
                using(Glass95.WithDarkForFixture(true)){shell.RefreshPanelTheme();await Task.Delay(70);Require(!Object.ReferenceEquals(previous,shell.Welcome)&&AppSettingsPalette.Dark&&shell.Welcome.SettingsPage=="화면"&&shell.Welcome.SearchSettings.Text=="투명도","Theme switch rebuilds settings and preserves search and page");Require(((SolidColorBrush)shell.Welcome.Surface.Background).Color==((SolidColorBrush)AppSettingsPalette.Surface).Color&&Native.RealtimeBackdrop(shell.Quick),"Theme switch updates opaque settings and live panel together");if(ui==95)Program.Save(shell.Welcome.Surface,760,720,Path.Combine(AppLog.Data,"settings-dark.png"));}
                shell.RefreshPanelTheme();await Task.Delay(50);Require(!AppSettingsPalette.Dark&&((SolidColorBrush)shell.Welcome.Surface.Background).Color==((SolidColorBrush)AppSettingsPalette.Surface).Color,"Returning to light restores settings palette");shell.Welcome.ReleaseIdle();shell.Welcome=null;shell.Quick.Close();shell.Quick=null;
            }
        }
        static async Task BackgroundChecks(System.Windows.Forms.Screen screen)
        {
            int kind=Preferences.Current.DockBackgroundKind;bool solid=Preferences.Current.DockSolidBackground;string color=Preferences.Current.DockBackgroundColor,file=Preferences.Current.DockBackgroundImage;GlassWindow surface=null;
            try{Preferences.Current.DockBackgroundKind=1;Preferences.Current.DockSolidBackground=true;Preferences.Current.DockBackgroundColor="#FF142033";surface=new GlassWindow {DockSurface=true};surface.SetMaterial(LightPanel.DockGlass,LightPanel.DockSolid);surface.ShowAt(screen.Bounds,20,20,300,44);Require(((SolidColorBrush)surface.Surface.Background).Color.R==20&&Native.BlurOpacity(surface)==0&&((SolidColorBrush)DockAppearance.Foreground).Color.R>240,"Custom dock color has a readable contrasting foreground and no blur");
                string image=Path.Combine(AppLog.Data,"custom-dock.png");var visual=new DrawingVisual();using(var drawing=visual.RenderOpen()){drawing.DrawRectangle(Brushes.Coral,null,new Rect(0,0,96,36));drawing.DrawRectangle(Brushes.SteelBlue,null,new Rect(48,0,48,36));}var bitmap=new RenderTargetBitmap(96,36,96,96,PixelFormats.Pbgra32);bitmap.Render(visual);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(image))encoder.Save(stream);Preferences.Current.DockSolidBackground=false;Preferences.Current.DockBackgroundKind=2;Preferences.Current.DockBackgroundImage=image;var requested=DockAppearance.Background;
                for(int i=0;i<150&&!(DockAppearance.Background is ImageBrush);i++)await Task.Delay(20);surface.RefreshGlassMaterial();var brush=surface.Surface.Background as ImageBrush;Require(brush!=null&&brush.IsFrozen&&Object.ReferenceEquals(brush,DockAppearance.Background)&&Native.BlurOpacity(surface)==0,"Custom dock image decodes once and is shared without a live backdrop");
            }finally{if(surface!=null)surface.Close();Preferences.Current.DockBackgroundKind=kind;Preferences.Current.DockSolidBackground=solid;Preferences.Current.DockBackgroundColor=color;Preferences.Current.DockBackgroundImage=file;}
        }
        internal static void Validate(List<string> checks)
        {
            int layouts=0;foreach(int edge in new[]{0,1,2,3})foreach(double scale in new[]{1.0,1.25,1.5,2.0,2.5})foreach(var origin in new[]{new System.Drawing.Point(0,0),new System.Drawing.Point(-2560,-800)})foreach(int count in new[]{0,4,20,80}){
                var screen=new System.Drawing.Rectangle(origin.X,origin.Y,(int)(1280*scale),(int)(800*scale));var fit=DockLayout.Compute(screen,scale,count,58,true,68,edge);var area=new Rect(0,0,1280,800);
                var apps=DockGeometry.Rect(screen,scale,edge,new Rect(fit.AppX,fit.Y,fit.AppWidth,44));var start=DockGeometry.Rect(screen,scale,edge,new Rect(fit.StartX,fit.Y+2,40,40));var status=DockGeometry.Rect(screen,scale,edge,new Rect(fit.StatusX,fit.Y-(DockGeometry.Vertical(edge)?10:0),fit.StatusWidth,DockGeometry.Vertical(edge)?64:44));Require(Inside(area,apps)&&Inside(area,start)&&Inside(area,status)&&!apps.IntersectsWith(status)&&!apps.IntersectsWith(start),"Dock geometry must fit and separate its surfaces on every edge");
                var work=new Native.RectI {Left=screen.Left,Top=screen.Top,Right=screen.Right,Bottom=screen.Bottom};var reserved=AppBarReservation.Reservation(screen,scale,work,false,edge);Require((edge==0||edge==2?reserved.Right-reserved.Left:reserved.Bottom-reserved.Top)==(int)Math.Round(68*scale),"Work area reserves the selected edge");var hidden=AppBarReservation.Reservation(screen,scale,work,true,edge);Require((edge==0||edge==2?hidden.Right-hidden.Left:hidden.Bottom-hidden.Top)==0,"Auto hide releases the selected edge");
                var reveal=DockGeometry.Reveal(screen,edge);Require((DockGeometry.Vertical(edge)?reveal.Right-reveal.Left:reveal.Bottom-reveal.Top)==2,"Reveal strip is two physical pixels at each edge");
                var panel=DockGeometry.Popup(screen,scale,380,540,edge);Require(Inside(area,panel)&&!panel.IntersectsWith(status),"Panels open inward without crossing status");
                var popup=DockGeometry.Beside(apps,new Size(240,180),area,edge);Require(Inside(area,popup),"Overflow and previews stay in monitor bounds");
                double mediaStart=DockGeometry.Vertical(edge)?1280-(edge==2?80:12):fit.StartX,mediaY=DockGeometry.Vertical(edge)?744:fit.Y;foreach(bool open in new[]{false,true}){var media=NowBarLayout.Fit(1280,800,mediaStart,mediaY,600,open,false,0,true,edge);Require(Inside(area,media.Bounds),"Media player stays on screen at each edge");}layouts++;
            }
            checks.Add("Four independent dock edges, work-area and reveal-strip geometry, inward popups and media placement pass at five DPI scales and negative origins ("+layouts+" layouts)");
        }
        internal static int Run()
        {
            var app=new Application {ShutdownMode=ShutdownMode.OnExplicitShutdown};ShellController shell=null;WelcomeWindow settings=null;QuickWindow quick=null;NotificationWindow center=null;DetailWindow detail=null;DockHost dock=null;IDisposable palette=null,pointer=null;int result=1,oldUI=Preferences.Current.UIVersion,oldEdge=Preferences.Current.DockEdge;bool oldBlur=Preferences.Current.Blur,oldAnimations=Preferences.Current.Animations;var samples=new List<object>();
            app.Dispatcher.BeginInvoke(new Action(async()=>{try{
                Program.Inspectable=true;Directory.CreateDirectory(AppLog.Data);Validate(new List<string>());Preferences.Current.UIVersion=ReleaseFeatures.GlassUI?95:90;Preferences.Current.DockEdge=3;Preferences.Current.Blur=true;Preferences.Current.Animations=false;pointer=MenuDismiss.WithSyntheticPointerForFixture();palette=Glass95.WithDarkForFixture(false);shell=new ShellController(true);var screen=System.Windows.Forms.Screen.PrimaryScreen;
                settings=new WelcomeWindow(shell);shell.Welcome=settings;settings.ShowAt(screen.Bounds,20,20,760,720);await Task.Delay(80);Require(settings.VisibleSettingsSections==settings.SettingsSections&&settings.VisibleSettingsCards==3,"All settings categories start visible");
                foreach(var button in Children<Button>(settings).Where(b=>b.Content is Grid&&new[]{"데스크톱","패널 선택","시작과 검색","미디어 플레이어","복구","PC 호환성","화면","움직임","충전 소리"}.Contains(AutomationProperties.GetName(b)))){var row=(Grid)button.Content;var icon=Children<Border>(row).First(b=>b.Child is Glyph);var label=row.Children.OfType<TextBlock>().First();var a=icon.TransformToAncestor(row).TransformBounds(new Rect(icon.RenderSize));var labelBounds=label.TransformToAncestor(row).TransformBounds(new Rect(label.RenderSize));Require(Math.Abs(a.Y+a.Height/2-labelBounds.Y-labelBounds.Height/2)<.6,"Settings category icon and name share a center line");}
                settings.SearchSettings.Text="ㅇㅁㅇㅁ";settings.UpdateLayout();Require(settings.SettingsNoResults&&settings.VisibleSettingsCards==0&&settings.VisibleSettingsSections==0,"No-results search removes category cards and separators");Program.Save(settings.Surface,760,720,Path.Combine(AppLog.Data,"settings-no-results.png"));
                settings.SearchSettings.Text="투명도";settings.UpdateLayout();Require(settings.SettingsNoResults&&settings.VisibleSettingsCards==0,"Removed transparency control is absent from search");settings.SearchSettings.Text="동적 블러";settings.UpdateLayout();Require(!settings.SettingsNoResults&&settings.VisibleSettingsSections==1&&settings.VisibleSettingsCards==1,"Search still finds a detail control without empty groups");settings.OpenSettings("화면");settings.UpdateLayout();Require(!Children<Slider>(settings).Any(s=>AutomationProperties.GetName(s)=="패널 투명도"),"No retired transparency slider is constructed");
                quick=new QuickWindow(shell);shell.Quick=quick;quick.ShowAt(screen.Bounds,40,40,380,650);quick.Refresh(shell.Power,64,35,false,true,true);await Task.Delay(70);var material=(LinearGradientBrush)PanelMaterial.Surface(false,ReleaseFeatures.GlassUI);Require(PanelMaterial.Transparency==70&&material.GradientStops.All(s=>Math.Abs(s.Color.A/255.0-.30)<.003)&&Native.RealtimeBackdrop(quick),"Fixed transparency retains live blur");Require(((SolidColorBrush)Paint.Text).Color.R<40,"Light panel text remains dark over white content");settings.SearchSettings.Clear();settings.SettingsHome();settings.UpdateLayout();Program.Save(settings.Surface,760,720,Path.Combine(AppLog.Data,"settings-home.png"));settings.ReleaseIdle();settings=null;shell.Welcome=null;quick.Close();quick=null;shell.Quick=null;
                foreach(int ui in (ReleaseFeatures.GlassUI?new[]{85,90,95}:new[]{85,90}))foreach(bool dark in new[]{false,true}){
                    palette.Dispose();palette=Glass95.WithDarkForFixture(dark);Preferences.Current.UIVersion=ui;quick=new QuickWindow(shell);shell.Quick=quick;quick.ShowAt(screen.Bounds,20,20,380,650);quick.Refresh(shell.Power,64,35,false,true,true);center=new NotificationWindow(shell);shell.Center=center;center.ShowAt(screen.Bounds,420,20,394,584);center.Refresh();detail=new DetailWindow(shell,"wifi",c=>Task.FromResult(new WirelessSnapshot()));detail.ShowAt(screen.Bounds,20,30,380,540);await Task.Delay(70);
                    var back=Children<Button>(detail).Single(b=>AutomationProperties.GetName(b)=="빠른 설정으로 돌아가기");Require(Math.Abs(back.ActualWidth-back.ActualHeight)<.01,"Detail back control is circular");Require(Native.RealtimeBackdrop(quick)&&Native.RealtimeBackdrop(center),"Quick and notifications use live blur in every UI and theme");foreach(var visible in new GlassWindow[]{quick,center,detail})ReleaseUIFeedbackChecks.CheckDisplayedSurface(visible);var ink=((SolidColorBrush)Paint.Text).Color;Require(dark?ink.R>220:ink.R<40,"Foreground follows the selected light or dark palette");
                    foreach(var button in Children<Button>(center).Where(b=>b.Content is TextBlock&&b.ActualWidth>0&&b.ActualHeight>0))Require(Math.Abs(((CornerRadius)button.Resources["ButtonRadius"]).TopLeft-Math.Min(button.ActualWidth,button.ActualHeight)/2)<.1,"Text actions keep capsule curvature");
                    Program.Save(quick.Surface,380,650,Path.Combine(AppLog.Data,"quick-"+ui+(dark?"-dark":"-light")+".png"));samples.Add(new {ui=ui,dark=dark,circle=true,pills=true,liveBlur=true});detail.Close();detail=null;center.Close();center=null;shell.Center=null;quick.Close();quick=null;shell.Quick=null;
                }
                palette.Dispose();palette=Glass95.WithDarkForFixture(false);Preferences.Current.UIVersion=ReleaseFeatures.GlassUI?95:90;shell.Desktop=true;var iconSource=ArtworkPalette.Sample(Colors.CornflowerBlue);shell.Pins=Enumerable.Range(1,48).Select(i=>new AppEntry {Name="고정 앱 "+i,Target="fixture:edge:"+i,Icon=iconSource,Pinned=true}).ToList();
                foreach(int edge in new[]{0,1,2,3}){Preferences.Current.DockEdge=edge;dock=new DockHost(shell,screen);dock.Show();await Task.Delay(130);ReleaseUIFeedbackChecks.CheckDisplayedSurface(dock.Apps);var actual=DockGeometry.ScreenRect(dock.Apps.Surface);var monitor=new Rect(screen.Bounds.Left,screen.Bounds.Top,screen.Bounds.Width,screen.Bounds.Height);Require(Inside(monitor,actual),"Actual dock HWND fits monitor on edge "+edge);Require(DockGeometry.Vertical(edge)?dock.Apps.Height>dock.Apps.Width:dock.Apps.Width>dock.Apps.Height,"Dock orientation matches its edge");Require(dock.Overflow.Count>0,"Many apps retain an overflow entry");dock.Overflow.Open();await Task.Delay(70);Require(dock.Overflow.IsOpen&&Inside(monitor,DockGeometry.ScreenRect(dock.Overflow.Popup.Surface)),"Overflow opens within monitor on edge "+edge);var clock=Children<Button>(dock.Status).Single(b=>AutomationProperties.GetName(b)=="알림센터");Require(clock.BorderThickness.Left==0&&clock.Background==Brushes.Transparent,"Clock has no added pill");dock.Overflow.Hide();dock.UpdateVisibility(false,true);dock.CompleteAutoHide(false);await Task.Delay(70);Native.RectI reveal;Native.GetWindowRect(dock.RevealHandle,out reveal);Require(reveal.Equals(DockGeometry.Reveal(screen.Bounds,edge)),"Actual reveal edge matches selected edge");dock.Reveal();await Task.Delay(70);Require(dock.DockVisible,"Selected edge reveals the dock");dock.Close();dock=null;}
                shell.Desktop=false;Preferences.Current.DockEdge=3;quick=new QuickWindow(shell);shell.Quick=quick;quick.ShowAt(screen.Bounds,20,20,380,650);Click(Children<Button>(quick).First(b=>AutomationProperties.GetName(b)=="달력 열기"));await Task.Delay(60);Require(shell.Calendar!=null&&shell.Calendar.IsVisible&&shell.Calendar.DayCells==42,"Panel clock opens a working calendar");shell.Calendar.Close();shell.Calendar=null;quick.HideImmediately();center=new NotificationWindow(shell);shell.Center=center;center.ShowAt(screen.Bounds,20,20,394,584);Click(Children<Button>(center).First(b=>AutomationProperties.GetName(b).StartsWith("빠른 설정")));await Task.Delay(100);Require(!center.IsVisible&&shell.Quick.IsVisible,"Notifications can return to quick settings");
                center.Close();center=null;shell.Center=null;quick=shell.Quick;quick.Close();quick=null;shell.Quick=null;await ThemeChecks(shell,screen);await BackgroundChecks(screen);await CompactStatusChecks.Run(shell,screen);await IssueFollowupChecks.Fallback(shell,screen);Require(LiveBackdrop.OrphanCount==0,"Feedback fixes leave no orphan backdrop hosts");
                AppLog.Json("beta-feedback-probe.json",new {passed=true,settingsSearchEmptyGroupsRemoved=true,categoryIconAlignment=true,transparencyFixed=70,transparencyControlRemoved=true,themeSamples=samples,dockFourEdges=true,actualRevealBounds=true,inwardOverflow=true,clockUnframed=true,calendar=true,notificationReturn=true,osInputSent=false,osThemeChanged=false,nativeTaskbarChanged=false});result=0;
            }catch(Exception error){AppLog.Json("beta-feedback-probe.json",new {passed=false,error=error.ToString(),themeSamples=samples});}finally{
                if(dock!=null)dock.Close();if(detail!=null)detail.Close();if(settings!=null)settings.ReleaseIdle();if(quick!=null)quick.Close();if(center!=null)center.Close();if(shell!=null)shell.Dispose();if(pointer!=null)pointer.Dispose();if(palette!=null)palette.Dispose();Preferences.Current.UIVersion=oldUI;Preferences.Current.DockEdge=oldEdge;Preferences.Current.Blur=oldBlur;Preferences.Current.Animations=oldAnimations;app.Shutdown(result);
            }}),DispatcherPriority.ApplicationIdle);return app.Run();
        }
